                if (!decisions.researchBudget || decisions.researchBudget < 50000 || decisions.researchBudget > 200000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('research_warning'), 'warning');
                    return false;
                }
            } else if (period === 2) {
                var em1 = document.getElementById('entryMode1Select');
                if (em1) decisions.entryMode1 = em1.value;
                var em2 = document.getElementById('entryMode2Select');
                if (em2) decisions.entryMode2 = em2.value;
                var totalModeCost = (this.ENTRY_MODES[decisions.entryMode1] || {}).cost + (this.ENTRY_MODES[decisions.entryMode2] || {}).cost;
                var availableCash = window.mySimulation.state.domainState.cash;
                if (totalModeCost > availableCash) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_exceeded_warning'), 'warning');
                    return false;
                }
            } else if (period === 3) {
                var rsSel = document.getElementById('responseStrategySelect');
                if (rsSel) decisions.responseStrategy = rsSel.value;
                var mbInput = document.getElementById('marketingBudgetInput');
                if (mbInput) decisions.marketingBudget = parseInt(mbInput.value);
                if (!decisions.marketingBudget || decisions.marketingBudget < 200000 || decisions.marketingBudget > 800000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('marketing_warning'), 'warning');
                    return false;
                }
                var responseCost = decisions.responseStrategy === 'accelerate' ? 400000 : 0;
                if ((decisions.marketingBudget + responseCost) > window.mySimulation.state.domainState.cash) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_exceeded_warning'), 'warning');
                    return false;
                }
            } else if (period === 4) {
                var locInput = document.getElementById('localizationInput');
                if (locInput) decisions.localizationLevel = parseInt(locInput.value);
                var ppInput = document.getElementById('pricePointInput');
                if (ppInput) decisions.pricePoint = parseInt(ppInput.value);
                if (!decisions.pricePoint || decisions.pricePoint < 12 || decisions.pricePoint > 28) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('price_warning'), 'warning');
                    return false;
                }
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var investment = 0;
            var revenueImpact = 0;
            var scoreGain = 0;
            var description = '';

            if (period === 1) {
                investment = d.researchBudget;
                ds.marketPriority = d.marketPriority;
                ds.markets = this.MARKET_COMBOS[d.marketPriority] || ['usa', 'mexico'];
                ds.researchBudget = d.researchBudget;
                ds.researchQuality = Math.min(100, Math.round((d.researchBudget / 200000) * 100));

                var m1 = this.MARKET_DATA[ds.markets[0]];
                var m2 = this.MARKET_DATA[ds.markets[1]];
                var combinedAttractiveness = (m1.attractiveness + m2.attractiveness) / 2;
                var researchBonus = ds.researchQuality * 0.15;
                scoreGain = Math.round(combinedAttractiveness * 10 + researchBonus);

                var baseRevenue = (m1.size * 0.001 + m2.size * 0.001) * (1 + ds.researchQuality / 200);
                revenueImpact = Math.round(baseRevenue);

                var mNames = { usa: 'USA', mexico: 'Mexico', europe: 'Europe' };
                description = mNames[ds.markets[0]] + ' + ' + mNames[ds.markets[1]];

            } else if (period === 2) {
                var mode1 = this.ENTRY_MODES[d.entryMode1];
                var mode2 = this.ENTRY_MODES[d.entryMode2];
                investment = mode1.cost + mode2.cost;
                ds.entryMode1 = d.entryMode1;
                ds.entryMode2 = d.entryMode2;
                ds.entryInvestment = investment;

                var controlScore = (mode1.control + mode2.control) / 2;
                var speedScore = 10 - ((mode1.speed + mode2.speed) / 2) / 1.8;
                var riskPenalty = (mode1.risk + mode2.risk) / 2;
                scoreGain = Math.round(controlScore * 4 + speedScore * 3 - riskPenalty * 1.5);

                var m1data = this.MARKET_DATA[ds.markets[0]];
                var m2data = this.MARKET_DATA[ds.markets[1]];
                revenueImpact = Math.round(
                    m1data.size * 0.002 * mode1.revMult +
                    m2data.size * 0.002 * mode2.revMult
                );

                description = d.entryMode1 + ' / ' + d.entryMode2;

            } else if (period === 3) {
                ds.responseStrategy = d.responseStrategy;
                ds.marketingBudget = d.marketingBudget;
                var responseCost = 0;
                var marketShareMult = 1.0;
                var marginEffect = 0;

                if (d.responseStrategy === 'accelerate') {
                    responseCost = 400000;
                    marketShareMult = 1.35;
                    marginEffect = -0.06;
                    scoreGain = 28;
                } else if (d.responseStrategy === 'maintain') {
                    responseCost = 0;
                    marketShareMult = 1.0;
                    marginEffect = 0.02;
                    scoreGain = 22;
                } else {
                    responseCost = 0;
                    marketShareMult = 0.7;
                    marginEffect = 0.09;
                    scoreGain = 25;
                }

                investment = responseCost + d.marketingBudget;
                var marketingEffect = Math.min(2.0, d.marketingBudget / 400000);
                ds.competitiveAdvantage = Math.round(marketShareMult * marketingEffect * 50);

                var m1rev = this.MARKET_DATA[ds.markets[0]];
                revenueImpact = Math.round(m1rev.size * 0.003 * marketShareMult * marketingEffect);
                ds.projectedMargin = 0.22 + marginEffect;

                description = d.responseStrategy;

            } else if (period === 4) {
                ds.localizationLevel = d.localizationLevel;
                ds.pricePoint = d.pricePoint;

                var locCost = d.localizationLevel * 40000;
                investment = locCost;

                var priceOptimal = 20;
                var priceDiff = Math.abs(d.pricePoint - priceOptimal);
                var priceScore = Math.max(0, 10 - priceDiff * 1.2);

                var locBonus = 0;
                if (d.localizationLevel >= 2 && d.localizationLevel <= 4) {
                    locBonus = 8;
                } else if (d.localizationLevel === 5) {
                    locBonus = 4;
                } else {
                    locBonus = 2;
                }

                scoreGain = Math.round(priceScore * 2 + locBonus + ds.competitiveAdvantage * 0.2);

                var volumeFactor = 1 + (5 - priceDiff) * 0.05;
                var localFactor = 1 + (d.localizationLevel - 1) * 0.06;
                var m1f = this.MARKET_DATA[ds.markets[0]];
                var m2f = this.MARKET_DATA[ds.markets[1]];
                revenueImpact = Math.round(
                    (m1f.size * 0.004 + m2f.size * 0.003) * volumeFactor * localFactor
                );

                ds.projectedMarketShare = Math.round(
                    (ds.competitiveAdvantage * 0.06 + priceScore * 0.3 + locBonus * 0.2) * 10
                ) / 10;

                description = 'Loc:' + d.localizationLevel + ' / $' + d.pricePoint + '/kg';
            }

            ds.cash -= investment;
            ds.totalInvested += investment;
            ds.strategicScore += Math.max(0, scoreGain);
            ds.projectedRevenueY3 += revenueImpact;

            ds.investmentHistory.push(investment);
            ds.revenueHistory.push(ds.projectedRevenueY3);
            ds.scoreHistory.push(ds.strategicScore);
            ds.roundDescriptions.push(description);

            // --- Persist a 0-100 overall score for the grading/reporting layer ---
            // Contract: the DB grade + reports resolve domainState.performance.overallScore, then domainState.score.
            // The sim's headline metric is the cumulative strategicScore (shown live + charted); it compresses into a
            // high band (~110-190), so it is normalised to 0-100 by subtracting an 80-pt baseline and clamping.
            // NOTE: no 0-100 score existed before — this is a newly-introduced, transparent normalisation (see review; tune to taste).
            var overallScore = Math.max(0, Math.min(100, Math.round(ds.strategicScore - 80)));
            var perfGrade = 'Needs Improvement';
            if (overallScore >= 80) perfGrade = 'Excellent';
            else if (overallScore >= 60) perfGrade = 'Good';
            else if (overallScore >= 40) perfGrade = 'Satisfactory';
            ds.score = overallScore;
            ds.performance = { overallScore: overallScore, grade: perfGrade };

            var results = {
                period: period,
                overallScore: overallScore,
                score: overallScore,
                investment: investment,
                revenueImpact: revenueImpact,
                cumulativeRevenue: ds.projectedRevenueY3,
                scoreGain: scoreGain,
                totalScore: ds.strategicScore,
                cash: ds.cash,
                description: description
            };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext, domainState: ds });
            })(state.currentPeriod + 1), 500);

            return results;
        }

